package com.shale.data.dao;

import static com.shale.core.service.ContactServicePort.*;

import java.sql.*;
import java.time.Instant;
import java.util.*;
import com.shale.core.runtime.DbSessionProvider;

/** Transactional Phase 1C definition and classification mutation store. */
final class ContactMutationDao {
    private final DbSessionProvider db;
    private final EntityActionAuditDao audit = new EntityActionAuditDao();
    ContactMutationDao(DbSessionProvider db) { this.db=Objects.requireNonNull(db); }

    DefinitionMutationResult create(CreateDefinitionCommand c){return tx(c.shaleClientId(),c.actorUserId(),true,con->{
        validateDefinitionValues(c.category(),c.systemKey(),c.name(),c.abbreviation(),c.description(),c.color(),c.sortOrder());
        String key=normalizeKey(c.systemKey());
        if(c.globalDefinitionId()!=null){ DefinitionState g=requireDefinition(con,c.category(),c.globalDefinitionId()); if(g.tenant()!=null)throw new IllegalArgumentException("Override source must be a global definition."); if(!g.active()||g.deleted())throw new IllegalArgumentException("Override source must be a visible active global definition."); if(!g.key().equals(key))throw new IllegalArgumentException("Override must reuse the global SystemKey exactly."); }
        else if(globalKeyExists(con,c.category(),key)) throw new IllegalArgumentException("Custom SystemKey would shadow a global definition; create an override explicitly.");
        if(tenantKeyExists(con,c.category(),c.shaleClientId(),key,null))throw new IllegalArgumentException("A tenant definition already uses this SystemKey.");
        String sql="INSERT dbo."+table(c.category())+" (ShaleClientId,SystemKey,Name,"+(c.category()==DefinitionCategory.CREDENTIAL?"Abbreviation,":"")+"Description,Color,SortOrder,IsActive,CreatedByUserId) OUTPUT INSERTED.Id VALUES (?, ?, ?, "+(c.category()==DefinitionCategory.CREDENTIAL?"?, ":"")+"?, ?, ?, ?, ?)";
        int id; try(PreparedStatement ps=con.prepareStatement(sql)){int i=1;ps.setInt(i++,c.shaleClientId());ps.setString(i++,key);ps.setString(i++,clean(c.name()));if(c.category()==DefinitionCategory.CREDENTIAL)ps.setString(i++,clean(c.abbreviation()));setString(ps,i++,c.description());ps.setString(i++,normalizeColor(c.color()));ps.setInt(i++,c.sortOrder());ps.setBoolean(i++,c.active());ps.setInt(i,c.actorUserId());try(ResultSet rs=ps.executeQuery()){if(!rs.next())throw new IllegalStateException("Definition was not created.");id=rs.getInt(1);}}
        DefinitionMutationResult out=result(con,c.category(),id); auditDefinition(con,c.shaleClientId(),c.actorUserId(),out,c.globalDefinitionId()==null?EntityActionAuditEvent.Action.CREATED:EntityActionAuditEvent.Action.OVERRIDE_CREATED);return out;});}

    DefinitionMutationResult update(UpdateDefinitionCommand c){return tx(c.shaleClientId(),c.actorUserId(),true,con->{requireExpected(c.expectedRowVer());DefinitionState old=requireOwned(con,c.category(),c.definitionId(),c.shaleClientId());validateDefinitionValues(c.category(),old.key(),c.name(),c.abbreviation(),c.description(),c.color(),c.sortOrder());String sql="UPDATE dbo."+table(c.category())+" SET Name=?,"+(c.category()==DefinitionCategory.CREDENTIAL?"Abbreviation=?,":"")+"Description=?,Color=?,SortOrder=?,UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND RowVer=?";try(PreparedStatement ps=con.prepareStatement(sql)){int i=1;ps.setString(i++,clean(c.name()));if(c.category()==DefinitionCategory.CREDENTIAL)ps.setString(i++,clean(c.abbreviation()));setString(ps,i++,c.description());ps.setString(i++,normalizeColor(c.color()));ps.setInt(i++,c.sortOrder());ps.setInt(i++,c.actorUserId());ps.setInt(i++,c.definitionId());ps.setInt(i++,c.shaleClientId());ps.setBytes(i,c.expectedRowVer());stale(ps.executeUpdate());}DefinitionMutationResult out=result(con,c.category(),c.definitionId());auditDefinition(con,c.shaleClientId(),c.actorUserId(),out,EntityActionAuditEvent.Action.UPDATED);return out;});}

    DefinitionMutationResult lifecycle(DefinitionLifecycleCommand c,String operation){return tx(c.shaleClientId(),c.actorUserId(),true,con->{requireExpected(c.expectedRowVer());DefinitionState old=requireOwned(con,c.category(),c.definitionId(),c.shaleClientId());String set;EntityActionAuditEvent.Action action;
        if("remove".equals(operation)){set="IsDeleted=1,IsActive=0,DeletedAt=SYSUTCDATETIME(),DeletedByUserId=?";action=EntityActionAuditEvent.Action.REMOVED;}
        else if("restore".equals(operation)){if(!old.deleted())throw new IllegalArgumentException("Definition is not removed.");if(tenantKeyExists(con,c.category(),c.shaleClientId(),old.key(),c.definitionId()))throw new IllegalArgumentException("A tenant definition already uses this SystemKey.");set="IsDeleted=0,IsActive=?,DeletedAt=NULL,DeletedByUserId=NULL";action=EntityActionAuditEvent.Action.RESTORED;}
        else {if(old.deleted())throw new IllegalArgumentException("Removed definition must be restored first.");set="IsActive=?";action=c.active()?EntityActionAuditEvent.Action.ACTIVATED:EntityActionAuditEvent.Action.DEACTIVATED;}
        String sql="UPDATE dbo."+table(c.category())+" SET "+set+",UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND RowVer=?";try(PreparedStatement ps=con.prepareStatement(sql)){int i=1;if("remove".equals(operation))ps.setInt(i++,c.actorUserId());else ps.setBoolean(i++,c.active());ps.setInt(i++,c.actorUserId());ps.setInt(i++,c.definitionId());ps.setInt(i++,c.shaleClientId());ps.setBytes(i,c.expectedRowVer());stale(ps.executeUpdate());}DefinitionMutationResult out=result(con,c.category(),c.definitionId());auditDefinition(con,c.shaleClientId(),c.actorUserId(),out,action);return out;});}

    AssignmentMutationResult assign(AssignClassificationCommand c){return tx(c.shaleClientId(),c.actorUserId(),false,con->{validateContact(con,c.shaleClientId(),c.contactId());DefinitionState d=requireSelectable(con,c.category(),c.shaleClientId(),c.definitionId());String at=assignmentTable(c.category()),fk=fk(c.category());if(activeAssignmentExists(con,at,fk,c.shaleClientId(),c.contactId(),c.definitionId()))throw new IllegalArgumentException("This active assignment already exists.");int order=c.category()==DefinitionCategory.CREDENTIAL?(c.displayOrder()==null?nextOrder(con,c.shaleClientId(),c.contactId()):c.displayOrder()):0;if(order<0)throw new IllegalArgumentException("DisplayOrder must be nonnegative.");String sql="INSERT dbo."+at+" (ShaleClientId,ContactId,"+fk+","+(c.category()==DefinitionCategory.CREDENTIAL?"DisplayOrder,":"")+"CreatedByUserId) OUTPUT INSERTED.Id VALUES (?,?,?,"+(c.category()==DefinitionCategory.CREDENTIAL?"?,":"")+"?)";long id;try(PreparedStatement ps=con.prepareStatement(sql)){int i=1;ps.setInt(i++,c.shaleClientId());ps.setInt(i++,c.contactId());ps.setInt(i++,c.definitionId());if(c.category()==DefinitionCategory.CREDENTIAL)ps.setInt(i++,order);ps.setInt(i,c.actorUserId());try(ResultSet rs=ps.executeQuery()){rs.next();id=rs.getLong(1);}}if(c.category()==DefinitionCategory.CONTACT_TYPE&&"expert".equals(d.key()))setExpert(con,c.shaleClientId(),c.contactId(),true);AssignmentMutationResult out=assignmentResult(con,c.category(),id);auditAssignment(con,c.shaleClientId(),c.actorUserId(),out,EntityActionAuditEvent.Action.ADDED);return out;});}

    AssignmentMutationResult lifecycle(AssignmentLifecycleCommand c,boolean restore){return tx(c.shaleClientId(),c.actorUserId(),false,con->{requireExpected(c.expectedRowVer());validateContact(con,c.shaleClientId(),c.contactId());AssignmentMutationResult old=requireAssignment(con,c.category(),c.assignmentId(),c.shaleClientId(),c.contactId(),restore);if(restore){requireSelectable(con,c.category(),c.shaleClientId(),old.definitionId());if(activeAssignmentExists(con,assignmentTable(c.category()),fk(c.category()),c.shaleClientId(),c.contactId(),old.definitionId()))throw new IllegalArgumentException("An active assignment already exists.");}String sql="UPDATE dbo."+assignmentTable(c.category())+" SET IsDeleted=?,DeletedAt="+(restore?"NULL":"SYSUTCDATETIME()")+",DeletedByUserId="+(restore?"NULL":"?")+",UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND ContactId=? AND RowVer=?";try(PreparedStatement ps=con.prepareStatement(sql)){int i=1;ps.setBoolean(i++,!restore);if(!restore)ps.setInt(i++,c.actorUserId());ps.setInt(i++,c.actorUserId());ps.setLong(i++,c.assignmentId());ps.setInt(i++,c.shaleClientId());ps.setInt(i++,c.contactId());ps.setBytes(i,c.expectedRowVer());stale(ps.executeUpdate());}if(c.category()==DefinitionCategory.CONTACT_TYPE){DefinitionState d=requireDefinition(con,c.category(),old.definitionId());if("expert".equals(d.key())){if(restore)setExpert(con,c.shaleClientId(),c.contactId(),true);else recomputeExpert(con,c.shaleClientId(),c.contactId());}}AssignmentMutationResult out=assignmentResult(con,c.category(),c.assignmentId());auditAssignment(con,c.shaleClientId(),c.actorUserId(),out,restore?EntityActionAuditEvent.Action.RESTORED:EntityActionAuditEvent.Action.REMOVED);return out;});}

    List<AssignmentMutationResult> reorder(ReorderCredentialsCommand c){return tx(c.shaleClientId(),c.actorUserId(),false,con->{
        validateContact(con,c.shaleClientId(),c.contactId());
        List<CredentialOrderItem> items=c.orderedAssignments();
        Map<Long,byte[]> expected=new LinkedHashMap<>();
        for(var x:items){requireExpected(x.expectedRowVer());if(expected.putIfAbsent(x.assignmentId(),x.expectedRowVer())!=null)throw new IllegalArgumentException("Duplicate credential assignment ID.");}
        Map<Long,byte[]> active=new LinkedHashMap<>();
        try(PreparedStatement ps=con.prepareStatement("SELECT Id,RowVer FROM dbo.ContactCredentials WHERE ShaleClientId=? AND ContactId=? AND IsDeleted=0")){ps.setInt(1,c.shaleClientId());ps.setInt(2,c.contactId());try(ResultSet rs=ps.executeQuery()){while(rs.next())active.put(rs.getLong(1),rs.getBytes(2));}}
        if(!active.keySet().equals(expected.keySet()))throw new IllegalArgumentException("Reorder must contain the complete active credential set.");
        for(var entry:expected.entrySet())if(!Arrays.equals(active.get(entry.getKey()),entry.getValue()))throw new IllegalStateException("A credential assignment changed; reload and retry.");
        List<AssignmentMutationResult> out=new ArrayList<>();
        for(int i=0;i<items.size();i++){var x=items.get(i);try(PreparedStatement ps=con.prepareStatement("UPDATE dbo.ContactCredentials SET DisplayOrder=?,UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND ContactId=? AND IsDeleted=0 AND RowVer=?")){ps.setInt(1,i);ps.setInt(2,c.actorUserId());ps.setLong(3,x.assignmentId());ps.setInt(4,c.shaleClientId());ps.setInt(5,c.contactId());ps.setBytes(6,x.expectedRowVer());stale(ps.executeUpdate());}out.add(assignmentResult(con,DefinitionCategory.CREDENTIAL,x.assignmentId()));}
        audit.append(con,EntityActionAuditEvent.now(c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.EntityType.CONTACT_CREDENTIAL,c.contactId(),EntityActionAuditEvent.Action.REORDERED,null,null,Map.of(EntityActionAuditEvent.MetadataKey.CONTACT_ID,c.contactId(),EntityActionAuditEvent.MetadataKey.ORDERING_COUNT,items.size())));return List.copyOf(out);});}

    void aggregate(UpdateContactProfileCommand c){Objects.requireNonNull(c,"command");tx(c.shaleClientId(),c.actorUserId(),false,con->{
        validateContact(con,c.shaleClientId(),c.contactId());
        validateName(c.displayName(),100,"Display Name");
        validateName(c.structuredName().prefix(),50,"Prefix"); validateName(c.structuredName().firstName(),100,"First Name");
        validateName(c.structuredName().middleName(),100,"Middle Name"); validateName(c.structuredName().lastName(),100,"Last Name");
        validateName(c.structuredName().preferredName(),100,"Preferred Name"); validateName(c.structuredName().suffix(),50,"Suffix");
        if(blank(c.displayName())&&blank(c.structuredName().firstName())&&blank(c.structuredName().lastName()))throw new IllegalArgumentException("Display Name, First Name, or Last Name is required.");
        prevalidateIntent(con,c,DefinitionCategory.CONTACT_TYPE,c.contactTypes());
        prevalidateIntent(con,c,DefinitionCategory.SPECIALTY,c.specialties());
        prevalidateIntent(con,c,DefinitionCategory.CREDENTIAL,c.credentials());
		prevalidateContactUpdatedAt(con,c);
		Map<Long,PointState> phones=inventory(con,"ContactPhoneNumbers",c);
		Map<Long,PointState> emails=inventory(con,"ContactEmailAddresses",c);
		Map<Long,PointState> addresses=inventory(con,"ContactAddresses",c);
		validatePhones(c.phoneNumbers(),phones); validateEmails(c.emailAddresses(),emails); validateAddresses(c.addresses(),addresses);
        List<IntendedAssignment> ordered=c.credentials().stream().filter(IntendedAssignment::selected).toList();
        Set<Long> requestedCredentialIds=new HashSet<>(); for(var x:ordered)if(x.existing())requestedCredentialIds.add(x.assignmentId());
        Set<Long> existingCredentialIds=activeAssignmentIds(con,DefinitionCategory.CREDENTIAL,c.shaleClientId(),c.contactId());
        Set<Long> explicitlyRemoved=c.credentials().stream().filter(x->x.existing()&&!x.selected()).map(IntendedAssignment::assignmentId).collect(java.util.stream.Collectors.toSet());
        Set<Long> complete=new HashSet<>(requestedCredentialIds);complete.addAll(explicitlyRemoved);
        if(!complete.equals(existingCredentialIds))throw new IllegalArgumentException("Credential intent must contain the complete active assignment set.");
        updateStructuredContact(con,c);
        applyIntent(con,c,DefinitionCategory.CONTACT_TYPE,c.contactTypes());
        applyIntent(con,c,DefinitionCategory.SPECIALTY,c.specialties());
        applyIntent(con,c,DefinitionCategory.CREDENTIAL,c.credentials());
        int order=0;for(var x:ordered){long id=x.existing()?x.assignmentId():activeAssignmentId(con,DefinitionCategory.CREDENTIAL,c.shaleClientId(),c.contactId(),x.definitionId());byte[] rv=x.existing()?x.expectedRowVer():assignmentResult(con,DefinitionCategory.CREDENTIAL,id).rowVer();try(PreparedStatement p=con.prepareStatement("UPDATE dbo.ContactCredentials SET DisplayOrder=?,UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND ContactId=? AND IsDeleted=0 AND RowVer=?")){p.setInt(1,order++);p.setInt(2,c.actorUserId());p.setLong(3,id);p.setInt(4,c.shaleClientId());p.setInt(5,c.contactId());p.setBytes(6,rv);stale(p.executeUpdate());}}
        audit.append(con,EntityActionAuditEvent.now(c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.EntityType.CONTACT_CREDENTIAL,c.contactId(),EntityActionAuditEvent.Action.REORDERED,null,null,Map.of(EntityActionAuditEvent.MetadataKey.CONTACT_ID,c.contactId(),EntityActionAuditEvent.MetadataKey.ORDERING_COUNT,ordered.size())));
		applyPhones(con,c,phones); applyEmails(con,c,emails); applyAddresses(con,c,addresses); projectLegacy(con,c);
        recomputeExpert(con,c.shaleClientId(),c.contactId());
        audit.append(con,EntityActionAuditEvent.now(c.shaleClientId(),c.actorUserId(),EntityActionAuditEvent.EntityType.CONTACT,c.contactId(),EntityActionAuditEvent.Action.UPDATED,null,null,Map.of(EntityActionAuditEvent.MetadataKey.CONTACT_ID,c.contactId(),EntityActionAuditEvent.MetadataKey.ORDERING_COUNT,ordered.size())));
        return null;});}

	private record PointState(boolean deleted,byte[] rowVer){}
	private static void prevalidateContactUpdatedAt(Connection con,UpdateContactProfileCommand c)throws SQLException{try(var p=con.prepareStatement("SELECT UpdatedAt FROM dbo.Contacts WHERE Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0")){p.setInt(1,c.contactId());p.setInt(2,c.shaleClientId());try(var r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Contact is unavailable.");Timestamp t=r.getTimestamp(1);Instant actual=t==null?null:t.toInstant();if(!Objects.equals(actual,c.expectedContactUpdatedAt()))throw new IllegalStateException("The Contact changed; reload before saving.");}}}
	private static Map<Long,PointState> inventory(Connection con,String table,UpdateContactProfileCommand c)throws SQLException{Map<Long,PointState> m=new LinkedHashMap<>();try(var p=con.prepareStatement("SELECT Id,IsDeleted,RowVer FROM dbo."+table+" WHERE ShaleClientId=? AND ContactId=?")){p.setInt(1,c.shaleClientId());p.setInt(2,c.contactId());try(var r=p.executeQuery()){while(r.next())m.put(r.getLong(1),new PointState(r.getBoolean(2),r.getBytes(3)));}}return m;}
	private static void common(Long id,byte[] rv,String kind,boolean primary,boolean deleted,int sort,Set<String> kinds,Set<Long> ids,Map<Long,PointState> actual){if(!kinds.contains(normKind(kind)))throw new IllegalArgumentException("Invalid contact-point Kind.");if(sort<0)throw new IllegalArgumentException("SortOrder must be nonnegative.");if(deleted&&primary)throw new IllegalArgumentException("Removed contact points cannot be primary.");if(id==null){if(rv!=null&&rv.length>0)throw new IllegalArgumentException("New rows cannot have ExpectedRowVer.");}else{if(id<=0||!ids.add(id))throw new IllegalArgumentException("Duplicate or invalid contact-point ID.");PointState s=actual.get(id);if(s==null)throw new SecurityException("Contact-point ID does not belong to this Contact and tenant.");requireExpected(rv);if(!Arrays.equals(s.rowVer(),rv))throw new IllegalStateException("A contact point changed; reload before saving.");}}
	private static void finish(Set<Long> ids,Map<Long,PointState> actual,List<Integer> orders,int primaries){if(!ids.equals(actual.keySet()))throw new IllegalArgumentException("Contact-point intent must contain the complete loaded set.");if(primaries>1)throw new IllegalArgumentException("At most one active primary is allowed per category.");Collections.sort(orders);for(int i=0;i<orders.size();i++)if(orders.get(i)!=i)throw new IllegalArgumentException("Active contact-point ordering must be contiguous and zero based.");}
	private static void validatePhones(List<IntendedPhoneNumber> xs,Map<Long,PointState>a){Set<Long>ids=new HashSet<>();Set<String>values=new HashSet<>();List<Integer>o=new ArrayList<>();int p=0;for(var x:xs){common(x.id(),x.expectedRowVer(),x.kind(),x.primary(),x.deleted(),x.sortOrder(),Set.of("MOBILE","HOME","WORK","FAX","OTHER"),ids,a);String v=trimRequired(x.displayNumber(),255,"DisplayNumber");if(x.extension()!=null&&x.extension().trim().length()>20)throw new IllegalArgumentException("Extension is too long.");if(!x.deleted()){o.add(x.sortOrder());if(x.primary())p++;if(!values.add(normalizePhone(v)))throw new IllegalArgumentException("Duplicate active phone number.");}}finish(ids,a,o,p);}
	private static void validateEmails(List<IntendedEmailAddress> xs,Map<Long,PointState>a){Set<Long>ids=new HashSet<>();Set<String>values=new HashSet<>();List<Integer>o=new ArrayList<>();int p=0;for(var x:xs){common(x.id(),x.expectedRowVer(),x.kind(),x.primary(),x.deleted(),x.sortOrder(),Set.of("PERSONAL","WORK","OTHER"),ids,a);String v=trimRequired(x.emailAddress(),320,"EmailAddress");if(!v.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("EmailAddress format is invalid.");if(!x.deleted()){o.add(x.sortOrder());if(x.primary())p++;if(!values.add(v.toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("Duplicate active email address.");}}finish(ids,a,o,p);}
	private static void validateAddresses(List<IntendedAddress> xs,Map<Long,PointState>a){Set<Long>ids=new HashSet<>();List<Integer>o=new ArrayList<>();int p=0;for(var x:xs){common(x.id(),x.expectedRowVer(),x.kind(),x.primary(),x.deleted(),x.sortOrder(),Set.of("HOME","WORK","OTHER"),ids,a);limit(x.addressLine1(),255,"AddressLine1");limit(x.addressLine2(),255,"AddressLine2");limit(x.city(),100,"City");limit(x.stateOrProvince(),100,"StateOrProvince");limit(x.postalCode(),32,"PostalCode");if(x.countryCode()!=null&&!x.countryCode().trim().matches("[A-Za-z]{2}"))throw new IllegalArgumentException("CountryCode must be a two-letter code.");if(allBlank(x.addressLine1(),x.addressLine2(),x.city(),x.stateOrProvince(),x.postalCode(),x.countryCode(),x.legacyAddressText()))throw new IllegalArgumentException("Address content is required.");if(!x.deleted()){o.add(x.sortOrder());if(x.primary())p++;}}finish(ids,a,o,p);}
	private static String normKind(String s){return s==null?"":s.trim().toUpperCase(Locale.ROOT);} private static String trimRequired(String s,int n,String l){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException(l+" is required.");limit(s,n,l);return s.trim();} private static void limit(String s,int n,String l){if(s!=null&&s.trim().length()>n)throw new IllegalArgumentException(l+" is too long.");} private static boolean allBlank(String...s){for(String x:s)if(x!=null&&!x.trim().isEmpty())return false;return true;} private static String normalizePhone(String s){String v=s.trim();String digits=v.replaceAll("[^0-9]","");return v.startsWith("+")?"+"+digits:digits;}
	private void applyPhones(Connection con,UpdateContactProfileCommand c,Map<Long,PointState> old)throws SQLException{for(var x:c.phoneNumbers()){long id;if(x.id()==null){try(var p=con.prepareStatement("INSERT dbo.ContactPhoneNumbers(ShaleClientId,ContactId,Kind,DisplayNumber,NormalizedNumber,Extension,IsPrimary,SortOrder,CreatedByUserId) OUTPUT INSERTED.Id VALUES(?,?,?,?,?,?,?,?,?)")){p.setInt(1,c.shaleClientId());p.setInt(2,c.contactId());p.setString(3,normKind(x.kind()));p.setString(4,x.displayNumber().trim());p.setString(5,normalizePhone(x.displayNumber()));setString(p,6,x.extension());p.setBoolean(7,x.primary());p.setInt(8,x.sortOrder());p.setInt(9,c.actorUserId());try(var r=p.executeQuery()){r.next();id=r.getLong(1);}}auditPoint(con,c,EntityActionAuditEvent.EntityType.CONTACT_PHONE_NUMBER,id,EntityActionAuditEvent.Action.CREATED,x.kind(),x.primary());}else{id=x.id();boolean restore=old.get(id).deleted()&&!x.deleted(),remove=!old.get(id).deleted()&&x.deleted();try(var p=con.prepareStatement("UPDATE dbo.ContactPhoneNumbers SET Kind=?,DisplayNumber=?,NormalizedNumber=?,Extension=?,IsPrimary=?,SortOrder=?,IsDeleted=?,DeletedAt="+(x.deleted()?"COALESCE(DeletedAt,SYSUTCDATETIME())":"NULL")+",DeletedByUserId="+(x.deleted()?"COALESCE(DeletedByUserId,?)":"NULL")+",UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND ContactId=? AND RowVer=?")){int i=1;p.setString(i++,normKind(x.kind()));p.setString(i++,x.displayNumber().trim());p.setString(i++,normalizePhone(x.displayNumber()));setString(p,i++,x.extension());p.setBoolean(i++,x.deleted()?false:x.primary());p.setInt(i++,x.sortOrder());p.setBoolean(i++,x.deleted());if(x.deleted())p.setInt(i++,c.actorUserId());p.setInt(i++,c.actorUserId());p.setLong(i++,id);p.setInt(i++,c.shaleClientId());p.setInt(i++,c.contactId());p.setBytes(i,x.expectedRowVer());stale(p.executeUpdate());}auditPoint(con,c,EntityActionAuditEvent.EntityType.CONTACT_PHONE_NUMBER,id,remove?EntityActionAuditEvent.Action.REMOVED:restore?EntityActionAuditEvent.Action.RESTORED:EntityActionAuditEvent.Action.UPDATED,x.kind(),!x.deleted()&&x.primary());}}}
	private void applyEmails(Connection con,UpdateContactProfileCommand c,Map<Long,PointState> old)throws SQLException{for(var x:c.emailAddresses()){long id;if(x.id()==null){try(var p=con.prepareStatement("INSERT dbo.ContactEmailAddresses(ShaleClientId,ContactId,Kind,EmailAddress,NormalizedEmail,IsPrimary,SortOrder,CreatedByUserId) OUTPUT INSERTED.Id VALUES(?,?,?,?,?,?,?,?)")){p.setInt(1,c.shaleClientId());p.setInt(2,c.contactId());p.setString(3,normKind(x.kind()));p.setString(4,x.emailAddress().trim());p.setString(5,x.emailAddress().trim().toLowerCase(Locale.ROOT));p.setBoolean(6,x.primary());p.setInt(7,x.sortOrder());p.setInt(8,c.actorUserId());try(var r=p.executeQuery()){r.next();id=r.getLong(1);}}auditPoint(con,c,EntityActionAuditEvent.EntityType.CONTACT_EMAIL_ADDRESS,id,EntityActionAuditEvent.Action.CREATED,x.kind(),x.primary());}else{id=x.id();boolean restore=old.get(id).deleted()&&!x.deleted(),remove=!old.get(id).deleted()&&x.deleted();try(var p=con.prepareStatement("UPDATE dbo.ContactEmailAddresses SET Kind=?,EmailAddress=?,NormalizedEmail=?,IsPrimary=?,SortOrder=?,IsDeleted=?,DeletedAt="+(x.deleted()?"COALESCE(DeletedAt,SYSUTCDATETIME())":"NULL")+",DeletedByUserId="+(x.deleted()?"COALESCE(DeletedByUserId,?)":"NULL")+",UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND ContactId=? AND RowVer=?")){int i=1;p.setString(i++,normKind(x.kind()));p.setString(i++,x.emailAddress().trim());p.setString(i++,x.emailAddress().trim().toLowerCase(Locale.ROOT));p.setBoolean(i++,x.deleted()?false:x.primary());p.setInt(i++,x.sortOrder());p.setBoolean(i++,x.deleted());if(x.deleted())p.setInt(i++,c.actorUserId());p.setInt(i++,c.actorUserId());p.setLong(i++,id);p.setInt(i++,c.shaleClientId());p.setInt(i++,c.contactId());p.setBytes(i,x.expectedRowVer());stale(p.executeUpdate());}auditPoint(con,c,EntityActionAuditEvent.EntityType.CONTACT_EMAIL_ADDRESS,id,remove?EntityActionAuditEvent.Action.REMOVED:restore?EntityActionAuditEvent.Action.RESTORED:EntityActionAuditEvent.Action.UPDATED,x.kind(),!x.deleted()&&x.primary());}}}


    private void applyAddresses(Connection con,UpdateContactProfileCommand c,Map<Long,PointState> old)throws SQLException{for(var x:c.addresses()){long id;boolean edit=x.id()==null||x.valuesEdited();String legacy=edit?composeAddress(x):x.legacyAddressText();if(x.id()==null){try(var p=con.prepareStatement("INSERT dbo.ContactAddresses(ShaleClientId,ContactId,Kind,AddressLine1,AddressLine2,City,StateOrProvince,PostalCode,CountryCode,LegacyAddressText,IsPrimary,SortOrder,CreatedByUserId) OUTPUT INSERTED.Id VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)")){int i=1;p.setInt(i++,c.shaleClientId());p.setInt(i++,c.contactId());p.setString(i++,normKind(x.kind()));setString(p,i++,x.addressLine1());setString(p,i++,x.addressLine2());setString(p,i++,x.city());setString(p,i++,x.stateOrProvince());setString(p,i++,x.postalCode());p.setString(i++,x.countryCode()==null?null:x.countryCode().trim().toUpperCase(Locale.ROOT));p.setString(i++,legacy);p.setBoolean(i++,x.primary());p.setInt(i++,x.sortOrder());p.setInt(i,c.actorUserId());try(var r=p.executeQuery()){r.next();id=r.getLong(1);}}auditPoint(con,c,EntityActionAuditEvent.EntityType.CONTACT_ADDRESS,id,EntityActionAuditEvent.Action.CREATED,x.kind(),x.primary());}else{id=x.id();boolean restore=old.get(id).deleted()&&!x.deleted(),remove=!old.get(id).deleted()&&x.deleted();String values=edit?"AddressLine1=?,AddressLine2=?,City=?,StateOrProvince=?,PostalCode=?,CountryCode=?,LegacyAddressText=?,":"";try(var p=con.prepareStatement("UPDATE dbo.ContactAddresses SET Kind=?,"+values+"IsPrimary=?,SortOrder=?,IsDeleted=?,DeletedAt="+(x.deleted()?"COALESCE(DeletedAt,SYSUTCDATETIME())":"NULL")+",DeletedByUserId="+(x.deleted()?"COALESCE(DeletedByUserId,?)":"NULL")+",UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND ContactId=? AND RowVer=?")){int i=1;p.setString(i++,normKind(x.kind()));if(edit){setString(p,i++,x.addressLine1());setString(p,i++,x.addressLine2());setString(p,i++,x.city());setString(p,i++,x.stateOrProvince());setString(p,i++,x.postalCode());p.setString(i++,x.countryCode()==null?null:x.countryCode().trim().toUpperCase(Locale.ROOT));p.setString(i++,legacy);}p.setBoolean(i++,x.deleted()?false:x.primary());p.setInt(i++,x.sortOrder());p.setBoolean(i++,x.deleted());if(x.deleted())p.setInt(i++,c.actorUserId());p.setInt(i++,c.actorUserId());p.setLong(i++,id);p.setInt(i++,c.shaleClientId());p.setInt(i++,c.contactId());p.setBytes(i,x.expectedRowVer());stale(p.executeUpdate());}auditPoint(con,c,EntityActionAuditEvent.EntityType.CONTACT_ADDRESS,id,remove?EntityActionAuditEvent.Action.REMOVED:restore?EntityActionAuditEvent.Action.RESTORED:EntityActionAuditEvent.Action.UPDATED,x.kind(),!x.deleted()&&x.primary());}}}
    /** Conservative compatibility rendering: nonblank components in postal-reading order, separated by comma-space. */
    static String composeAddress(IntendedAddress x){List<String> parts=new ArrayList<>();for(String v:List.of(nvl(x.addressLine1()),nvl(x.addressLine2()),nvl(x.city()),nvl(x.stateOrProvince()),nvl(x.postalCode()),nvl(x.countryCode())))if(!v.isBlank())parts.add(v.trim());String out=String.join(", ",parts);return out.isBlank()?trimNull(x.legacyAddressText()):out;}private static String nvl(String x){return x==null?"":x;}private static String trimNull(String x){return x==null||x.trim().isEmpty()?null:x.trim();}
    private static void projectLegacy(Connection con,UpdateContactProfileCommand c)throws SQLException{String[] columns={"PhoneCell","PhoneHome","PhoneWork","EmailPersonal","EmailWork","EmailOther","AddressHome","AddressWork","AddressOther"};String[] tables={"ContactPhoneNumbers","ContactPhoneNumbers","ContactPhoneNumbers","ContactEmailAddresses","ContactEmailAddresses","ContactEmailAddresses","ContactAddresses","ContactAddresses","ContactAddresses"};String[] values={"DisplayNumber","DisplayNumber","DisplayNumber","EmailAddress","EmailAddress","EmailAddress","LegacyAddressText","LegacyAddressText","LegacyAddressText"};String[] kinds={"MOBILE","HOME","WORK","PERSONAL","WORK","OTHER","HOME","WORK","OTHER"};StringJoiner q=new StringJoiner(",","UPDATE dbo.Contacts SET "," WHERE Id=? AND ShaleClientId=?");for(int n=0;n<columns.length;n++)q.add(columns[n]+"=(SELECT TOP(1) "+values[n]+" FROM dbo."+tables[n]+" WHERE ShaleClientId=? AND ContactId=? AND IsDeleted=0 AND Kind=N'"+kinds[n]+"' ORDER BY IsPrimary DESC,SortOrder,Id)");try(var p=con.prepareStatement(q.toString())){int i=1;for(int n=0;n<9;n++){p.setInt(i++,c.shaleClientId());p.setInt(i++,c.contactId());}p.setInt(i++,c.contactId());p.setInt(i,c.shaleClientId());stale(p.executeUpdate());}}
    private void auditPoint(Connection con,UpdateContactProfileCommand c,EntityActionAuditEvent.EntityType type,long id,EntityActionAuditEvent.Action action,String kind,boolean primary)throws SQLException{audit.append(con,EntityActionAuditEvent.now(c.shaleClientId(),c.actorUserId(),type,id,action,EntityActionAuditEvent.EntityType.CONTACT,(long)c.contactId(),Map.of(EntityActionAuditEvent.MetadataKey.CONTACT_ID,c.contactId(),EntityActionAuditEvent.MetadataKey.KIND,normKind(kind),EntityActionAuditEvent.MetadataKey.PRIMARY,primary)));}

    private static void validateName(String value,int max,String label){if(value!=null&&value.trim().length()>max)throw new IllegalArgumentException(label+" is too long.");}
    private static boolean blank(String v){return v==null||v.isBlank();}
    private static void prevalidateIntent(Connection con,UpdateContactProfileCommand c,DefinitionCategory k,List<IntendedAssignment> intent)throws SQLException{
        Set<Integer> selected=new HashSet<>();Set<Long> ids=new HashSet<>();
        for(var x:intent){if(x.definitionId()<=0)throw new IllegalArgumentException("Definition ID must be positive.");if(x.selected()&&!selected.add(x.definitionId()))throw new IllegalArgumentException("Duplicate selected definition ID.");if(x.existing()){requireExpected(x.expectedRowVer());if(!ids.add(x.assignmentId()))throw new IllegalArgumentException("Duplicate assignment ID.");AssignmentMutationResult a=assignmentResult(con,k,x.assignmentId());if(a.contactId()!=c.contactId()||a.definitionId()!=x.definitionId())throw new SecurityException("Assignment identity does not match the Contact and definition.");if(!Arrays.equals(a.rowVer(),x.expectedRowVer()))throw new IllegalStateException("An assignment changed; reload before saving.");}else if(x.selected())requireSelectable(con,k,c.shaleClientId(),x.definitionId());}
        if(!ids.equals(activeAssignmentIds(con,k,c.shaleClientId(),c.contactId())))throw new IllegalArgumentException("Assignment intent must contain the complete active assignment set.");
    }
    private void applyIntent(Connection con,UpdateContactProfileCommand c,DefinitionCategory k,List<IntendedAssignment> intent)throws SQLException{
        for(var x:intent){if(x.existing()){if(!x.selected()){mutateAssignment(con,c,k,x.assignmentId(),false,x.expectedRowVer());}}else if(x.selected()){
            Long removed=removedAssignmentId(con,k,c.shaleClientId(),c.contactId(),x.definitionId());
            if(removed!=null){byte[] rv=assignmentResult(con,k,removed).rowVer();mutateAssignment(con,c,k,removed,true,rv);}else insertAssignment(con,c,k,x.definitionId());
        }}
    }
    private void mutateAssignment(Connection con,UpdateContactProfileCommand c,DefinitionCategory k,long id,boolean restore,byte[] rv)throws SQLException{String sql="UPDATE dbo."+assignmentTable(k)+" SET IsDeleted=?,DeletedAt="+(restore?"NULL":"SYSUTCDATETIME()")+",DeletedByUserId="+(restore?"NULL":"?")+",UpdatedAt=SYSUTCDATETIME(),UpdatedByUserId=? WHERE Id=? AND ShaleClientId=? AND ContactId=? AND RowVer=?";try(PreparedStatement p=con.prepareStatement(sql)){int i=1;p.setBoolean(i++,!restore);if(!restore)p.setInt(i++,c.actorUserId());p.setInt(i++,c.actorUserId());p.setLong(i++,id);p.setInt(i++,c.shaleClientId());p.setInt(i++,c.contactId());p.setBytes(i,rv);stale(p.executeUpdate());}AssignmentMutationResult a=assignmentResult(con,k,id);auditAssignment(con,c.shaleClientId(),c.actorUserId(),a,restore?EntityActionAuditEvent.Action.RESTORED:EntityActionAuditEvent.Action.REMOVED);}
    private void insertAssignment(Connection con,UpdateContactProfileCommand c,DefinitionCategory k,int def)throws SQLException{requireSelectable(con,k,c.shaleClientId(),def);String sql="INSERT dbo."+assignmentTable(k)+" (ShaleClientId,ContactId,"+fk(k)+","+(k==DefinitionCategory.CREDENTIAL?"DisplayOrder,":"")+"CreatedByUserId) OUTPUT INSERTED.Id VALUES (?,?,?,"+(k==DefinitionCategory.CREDENTIAL?"0,":"")+"?)";try(PreparedStatement p=con.prepareStatement(sql)){p.setInt(1,c.shaleClientId());p.setInt(2,c.contactId());p.setInt(3,def);p.setInt(4,c.actorUserId());try(ResultSet r=p.executeQuery()){r.next();auditAssignment(con,c.shaleClientId(),c.actorUserId(),assignmentResult(con,k,r.getLong(1)),EntityActionAuditEvent.Action.ADDED);}}}
    private static void updateStructuredContact(Connection con,UpdateContactProfileCommand c)throws SQLException{
        String sql="UPDATE dbo.Contacts SET Name=?,Prefix=?,FirstName=?,MiddleName=?,LastName=?,PreferredName=?,Suffix=?,UpdatedAt=SYSUTCDATETIME() WHERE Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0 AND "+(c.expectedContactUpdatedAt()==null?"UpdatedAt IS NULL":"UpdatedAt=?");
        try(PreparedStatement p=con.prepareStatement(sql)){
            int i=1;
            setString(p,i++,c.displayName());
            setString(p,i++,c.structuredName().prefix());
            setString(p,i++,c.structuredName().firstName());
            setString(p,i++,c.structuredName().middleName());
            setString(p,i++,c.structuredName().lastName());
            setString(p,i++,c.structuredName().preferredName());
            setString(p,i++,c.structuredName().suffix());
            p.setInt(i++,c.contactId());
            p.setInt(i++,c.shaleClientId());
            if(c.expectedContactUpdatedAt()!=null)p.setTimestamp(i,Timestamp.from(c.expectedContactUpdatedAt()));
            stale(p.executeUpdate());
        }
    }
    private static Set<Long> activeAssignmentIds(Connection c,DefinitionCategory k,int t,int contact)throws SQLException{Set<Long>s=new HashSet<>();try(PreparedStatement p=c.prepareStatement("SELECT Id FROM dbo."+assignmentTable(k)+" WHERE ShaleClientId=? AND ContactId=? AND IsDeleted=0")){p.setInt(1,t);p.setInt(2,contact);try(ResultSet r=p.executeQuery()){while(r.next())s.add(r.getLong(1));}}return s;}
    private static long activeAssignmentId(Connection c,DefinitionCategory k,int t,int contact,int def)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT Id FROM dbo."+assignmentTable(k)+" WHERE ShaleClientId=? AND ContactId=? AND "+fk(k)+"=? AND IsDeleted=0")){p.setInt(1,t);p.setInt(2,contact);p.setInt(3,def);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalStateException("New assignment result missing.");return r.getLong(1);}}}
    private static Long removedAssignmentId(Connection c,DefinitionCategory k,int t,int contact,int def)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT TOP(1) Id FROM dbo."+assignmentTable(k)+" WHERE ShaleClientId=? AND ContactId=? AND "+fk(k)+"=? AND IsDeleted=1 ORDER BY Id DESC")){p.setInt(1,t);p.setInt(2,contact);p.setInt(3,def);try(ResultSet r=p.executeQuery()){return r.next()?r.getLong(1):null;}}}

    private <T>T tx(int tenant,int actor,boolean admin,Work<T>w){if(tenant<=0||actor<=0)throw new IllegalArgumentException("Tenant and actor IDs must be positive.");try(Connection con=db.requireConnection()){boolean ac=con.getAutoCommit();con.setAutoCommit(false);try{verifyTenant(con,tenant);validateActor(con,tenant,actor,admin);T out=w.run(con);con.commit();return out;}catch(Exception e){con.rollback();if(e instanceof RuntimeException r)throw r;throw new IllegalStateException("Contact mutation failed.",e);}finally{con.setAutoCommit(ac);}}catch(SQLException e){throw new IllegalStateException("Contact mutation failed.",e);}}
    private interface Work<T>{T run(Connection c)throws Exception;}
    private static void verifyTenant(Connection c,int t)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT CAST(SESSION_CONTEXT(N'ShaleClientId') AS INT)");ResultSet r=p.executeQuery()){if(!r.next()||r.getObject(1)==null||r.getInt(1)!=t)throw new SecurityException("ShaleClientId session context mismatch.");}}
    private static void validateActor(Connection c,int t,int u,boolean admin)throws SQLException{String sql="SELECT 1 FROM dbo.Users WHERE id=? AND ShaleClientId=? AND ISNULL(is_deleted,0)=0 AND ISNULL(IsRemoved,0)=0"+(admin?" AND ISNULL(is_admin,0)=1":"");try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,u);p.setInt(2,t);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SecurityException(admin?"An active tenant administrator is required.":"An active tenant actor is required.");}}}
    private static void validateContact(Connection c,int t,int id)throws SQLException{if(id<=0)throw new IllegalArgumentException("ContactId must be positive.");try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM dbo.Contacts WHERE Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0")){p.setInt(1,id);p.setInt(2,t);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Active Contact is not available for this tenant.");}}}
    private record DefinitionState(int id,Integer tenant,String key,boolean active,boolean deleted){}
    private static DefinitionState requireDefinition(Connection c,DefinitionCategory k,int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT Id,ShaleClientId,SystemKey,IsActive,IsDeleted FROM dbo."+table(k)+" WHERE Id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next())return new DefinitionState(r.getInt(1),(Integer)r.getObject(2),r.getString(3),r.getBoolean(4),r.getBoolean(5));throw new IllegalArgumentException("Definition was not found.");}}}
    private static DefinitionState requireOwned(Connection c,DefinitionCategory k,int id,int t)throws SQLException{DefinitionState d=requireDefinition(c,k,id);if(d.tenant()==null)throw new SecurityException("Global definitions are read-only.");if(d.tenant()!=t)throw new SecurityException("Definition belongs to another tenant.");return d;}
    private static DefinitionState requireSelectable(Connection c,DefinitionCategory k,int t,int id)throws SQLException{DefinitionState d=requireDefinition(c,k,id);if(d.tenant()!=null&&d.tenant()!=t)throw new SecurityException("Definition belongs to another tenant.");if(!d.active()||d.deleted())throw new IllegalArgumentException("Definition is inactive or removed.");if(d.tenant()==null&&activeTenantKeyExists(c,k,t,d.key()))throw new IllegalArgumentException("Global definition is shadowed by a tenant override.");return d;}
    private static boolean globalKeyExists(Connection c,DefinitionCategory k,String key)throws SQLException{return keyExists(c,"SELECT 1 FROM dbo."+table(k)+" WHERE ShaleClientId IS NULL AND SystemKey=?",key,null,null);}
    private static boolean activeTenantKeyExists(Connection c,DefinitionCategory k,int t,String key)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM dbo."+table(k)+" WHERE ShaleClientId=? AND SystemKey=? AND IsDeleted=0")){p.setInt(1,t);p.setString(2,key);try(ResultSet r=p.executeQuery()){return r.next();}}}
    private static boolean tenantKeyExists(Connection c,DefinitionCategory k,int t,String key,Integer excluded)throws SQLException{return keyExists(c,"SELECT 1 FROM dbo."+table(k)+" WHERE ShaleClientId=? AND SystemKey=? AND (? IS NULL OR Id<>?)",key,t,excluded);}
    private static boolean keyExists(Connection c,String sql,String key,Integer tenant,Integer excluded)throws SQLException{try(PreparedStatement p=c.prepareStatement(sql)){int i=1;if(tenant!=null)p.setInt(i++,tenant);p.setString(i++,key);if(tenant!=null){if(excluded==null){p.setNull(i++,Types.INTEGER);p.setNull(i,Types.INTEGER);}else{p.setInt(i++,excluded);p.setInt(i,excluded);}}try(ResultSet r=p.executeQuery()){return r.next();}}}
    private static boolean activeAssignmentExists(Connection c,String at,String fk,int t,int contact,int def)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM dbo."+at+" WHERE ShaleClientId=? AND ContactId=? AND "+fk+"=? AND IsDeleted=0")){p.setInt(1,t);p.setInt(2,contact);p.setInt(3,def);try(ResultSet r=p.executeQuery()){return r.next();}}}
    private static AssignmentMutationResult requireAssignment(Connection c,DefinitionCategory k,long id,int t,int contact,boolean deleted)throws SQLException{AssignmentMutationResult a=assignmentResult(c,k,id);if(a.contactId()!=contact)throw new SecurityException("Assignment belongs to another Contact.");try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM dbo."+assignmentTable(k)+" WHERE Id=? AND ShaleClientId=? AND ContactId=? AND IsDeleted=?")){p.setLong(1,id);p.setInt(2,t);p.setInt(3,contact);p.setBoolean(4,deleted);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException(deleted?"Removed assignment was not found.":"Active assignment was not found.");}}return a;}
    private static DefinitionMutationResult result(Connection c,DefinitionCategory k,int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT SystemKey,Color,IsActive,IsDeleted,RowVer FROM dbo."+table(k)+" WHERE Id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalStateException("Definition result missing.");return new DefinitionMutationResult(k,id,r.getString(1),r.getString(2),r.getBoolean(3),r.getBoolean(4),r.getBytes(5));}}}
    private static AssignmentMutationResult assignmentResult(Connection c,DefinitionCategory k,long id)throws SQLException{String order=k==DefinitionCategory.CREDENTIAL?"DisplayOrder":"CAST(NULL AS int)";try(PreparedStatement p=c.prepareStatement("SELECT ContactId,"+fk(k)+","+order+",IsDeleted,RowVer FROM dbo."+assignmentTable(k)+" WHERE Id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Assignment was not found.");return new AssignmentMutationResult(k,id,r.getInt(1),r.getInt(2),(Integer)r.getObject(3),r.getBoolean(4),r.getBytes(5));}}}
    private static int nextOrder(Connection c,int t,int contact)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(MAX(DisplayOrder),-1)+1 FROM dbo.ContactCredentials WHERE ShaleClientId=? AND ContactId=? AND IsDeleted=0")){p.setInt(1,t);p.setInt(2,contact);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
    private static void setExpert(Connection c,int t,int contact,boolean v)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE dbo.Contacts SET IsExpert=? WHERE Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0")){p.setBoolean(1,v);p.setInt(2,contact);p.setInt(3,t);if(p.executeUpdate()!=1)throw new IllegalStateException("Contact Expert compatibility update failed.");}}
    private static void recomputeExpert(Connection c,int t,int contact)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE dbo.Contacts SET IsExpert=CASE WHEN EXISTS(SELECT 1 FROM dbo.ContactContactTypes a JOIN dbo.ContactTypes d ON d.Id=a.ContactTypeId WHERE a.ShaleClientId=? AND a.ContactId=? AND a.IsDeleted=0 AND d.SystemKey=N'expert') THEN 1 ELSE 0 END WHERE Id=? AND ShaleClientId=? AND ISNULL(IsDeleted,0)=0")){p.setInt(1,t);p.setInt(2,contact);p.setInt(3,contact);p.setInt(4,t);if(p.executeUpdate()!=1)throw new IllegalStateException("Contact Expert compatibility update failed.");}}
    private void auditDefinition(Connection c,int t,int actor,DefinitionMutationResult d,EntityActionAuditEvent.Action a)throws SQLException{audit.append(c,EntityActionAuditEvent.now(t,actor,entity(d.category()),d.definitionId(),a,null,null,Map.of(EntityActionAuditEvent.MetadataKey.DEFINITION_ID,d.definitionId(),EntityActionAuditEvent.MetadataKey.ACTIVE,d.active())));}
    private void auditAssignment(Connection c,int t,int actor,AssignmentMutationResult a,EntityActionAuditEvent.Action action)throws SQLException{audit.append(c,EntityActionAuditEvent.now(t,actor,assignmentEntity(a.category()),a.assignmentId(),action,null,null,Map.of(EntityActionAuditEvent.MetadataKey.CONTACT_ID,a.contactId(),EntityActionAuditEvent.MetadataKey.DEFINITION_ID,a.definitionId())));}
    private static EntityActionAuditEvent.EntityType entity(DefinitionCategory k){return switch(k){case CONTACT_TYPE->EntityActionAuditEvent.EntityType.CONTACT_TYPE;case SPECIALTY->EntityActionAuditEvent.EntityType.SPECIALTY;case CREDENTIAL->EntityActionAuditEvent.EntityType.CREDENTIAL_DEFINITION;};}
    private static EntityActionAuditEvent.EntityType assignmentEntity(DefinitionCategory k){return switch(k){case CONTACT_TYPE->EntityActionAuditEvent.EntityType.CONTACT_CONTACT_TYPE;case SPECIALTY->EntityActionAuditEvent.EntityType.CONTACT_SPECIALTY;case CREDENTIAL->EntityActionAuditEvent.EntityType.CONTACT_CREDENTIAL;};}
    private static String table(DefinitionCategory k){return switch(k){case CONTACT_TYPE->"ContactTypes";case SPECIALTY->"Specialties";case CREDENTIAL->"CredentialDefinitions";};}
    private static String assignmentTable(DefinitionCategory k){return switch(k){case CONTACT_TYPE->"ContactContactTypes";case SPECIALTY->"ContactSpecialties";case CREDENTIAL->"ContactCredentials";};}
    private static String fk(DefinitionCategory k){return switch(k){case CONTACT_TYPE->"ContactTypeId";case SPECIALTY->"SpecialtyId";case CREDENTIAL->"CredentialDefinitionId";};}
    private static String normalizeKey(String s){String v=clean(s).toLowerCase(Locale.ROOT);if(!v.matches("[a-z][a-z0-9]*(?:_[a-z0-9]+)*")||v.length()>64)throw new IllegalArgumentException("SystemKey must use lowercase snake_case.");return v;}
    private static void validateDefinitionValues(DefinitionCategory k,String key,String name,String abbreviation,String description,String color,int order){normalizeKey(key);normalizeColor(color);if(clean(name).length()>100)throw new IllegalArgumentException("Name is too long.");if(k==DefinitionCategory.CREDENTIAL&&(abbreviation==null||clean(abbreviation).length()>50))throw new IllegalArgumentException("Credential abbreviation is required and must be at most 50 characters.");if(description!=null&&description.trim().length()>500)throw new IllegalArgumentException("Description is too long.");if(order<0)throw new IllegalArgumentException("SortOrder must be nonnegative.");}
    static String normalizeColor(String value){if(value==null)throw new IllegalArgumentException("Color is required.");String color=value.trim().toUpperCase(Locale.ROOT);if(!color.matches("#[0-9A-F]{6}"))throw new IllegalArgumentException("Color is required and must use #RRGGBB format.");return color;}
    private static String clean(String s){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException("Required text is missing.");return s.trim();}
    private static void setString(PreparedStatement p,int i,String s)throws SQLException{if(s==null||s.trim().isEmpty())p.setNull(i,Types.NVARCHAR);else p.setString(i,s.trim());}
    private static void requireExpected(byte[] b){if(b==null||b.length==0)throw new IllegalArgumentException("ExpectedRowVer is required.");}
    private static void stale(int n){if(n!=1)throw new IllegalStateException("The row changed; reload and retry.");}
}
